/* ===== 30_orders: Key orders & Token orders, OTA Tax Invoices (USD), credit notes, SIM shipments in custody, OTA data (ord_) =====
   v09 model: OTA TECHNOLOGY DMCC invoices only Activation Keys and Service Tokens, in USD. SIM cards are never invoiced:
   they travel in custody (pro forma OTA-PF + receipt OTA-SR). Keys/tokens are issued when OTA Finance marks the invoice paid. */
const ord_sec=()=>t('ord.sec');
function ord_pl(n,base){return plural(n,{one:t(base+'.one'),few:t(base+'.few'),many:t(base+'.many'),other:t(base+'.other')});}
function ord_keysN(n){return fmtNum(n)+' '+ord_pl(n,'ord.key');}
function ord_toksN(n){return fmtNum(n)+' '+ord_pl(n,'ord.tok');}
function ord_simsN(n){return fmtNum(n)+' '+ord_pl(n,'ord.sim');}
function ord_allOrders(){return S.keyOrders.map(o=>Object.assign({type:'key'},{o})).concat(S.tokenOrders.map(o=>({type:'token',o})));}
function ord_find(id){const k=S.keyOrders.find(o=>o.id===id);if(k)return{type:'key',o:k};const t2=S.tokenOrders.find(o=>o.id===id);return t2?{type:'token',o:t2}:null;}
function ord_qtyOf(x){return x.type==='key'?x.o.qty:x.o.lines.reduce((a,l)=>a+l.qty,0);}
function ord_amountOf(x){return r2(x.type==='key'?x.o.qty*x.o.unit:x.o.lines.reduce((a,l)=>a+l.qty*l.unit,0));}
function ord_group(g){return ord_allOrders().filter(x=>x.o.group===g);}
const ORD_TONE={draft:'',awaiting_payment:'warn',paid:'ok',cancelled:'bad'};
function ord_stBadge(o){return ui.badge(t('ord.st.'+o.status),ORD_TONE[o.status]||'',true);}
function ord_invBadge(i){const s=invStatus(i);return ui.badge(t('ord.inv.st.'+s),s==='paid'?'ok':s==='overdue'?'bad':s==='cancelled'?'':'warn',true);}
function ord_fmtTrack(s){return String(s||'').replace(/(\d{4})(?=\d)/g,'$1 ');}
function ord_hasKeyOrder(){return S.keyOrders.some(o=>o.status!=='draft'&&o.status!=='cancelled');}
function ord_minKeys(){const m=orgMin();return ord_hasKeyOrder()?m.next:m.first;}
function ord_tokPlans(){const p={};allModels().forEach(x=>{if(x.model.planStatus==='approved'&&x.model.plan)p[x.model.plan]=1;});return PLANS.filter(x=>p[x]);}
function ord_qty(v){const s=String(v==null?'':v).replace(/[\s  ,]/g,'');if(s==='')return 0;return /^\d+$/.test(s)?parseInt(s,10):NaN;}
function ord_noPerm(perm){return ui.note('warn',t('c.noPerm',{r:esc(roleName(actor().role))}));}
function ord_vatLine(i,lang){return lang==='en'?i.vatLabel:((i.vatLabelL2&&i.vatLabelL2[lang])||i.vatLabel);}

/* ---------- placing orders ---------- */
// keys: number, toks: [[plan,term,qty]], mode: 'combined'|'separate', draft: bool → {orders, invoices}
function ord_place(cc,keys,toks,mode,draft){const pl=priceList(cc);const created=iso(now());const grp=uid('g');const out={orders:[],invoices:[]};
 const ko=keys>0?{id:uid('ko'),no:orderNo('key'),cc,qty:keys,unit:pl.key,status:draft?'draft':'awaiting_payment',invoiceId:null,group:grp,mode,priceVer:pl.ver,createdAt:created,by:actorName()}:null;
 const to=toks.length?{id:uid('to'),no:orderNo('token'),cc,lines:toks.map(([p,tm,q])=>({plan:p,term:tm,qty:q,unit:pl.tokens[p][tm]})),status:draft?'draft':'awaiting_payment',invoiceId:null,group:grp,mode,priceVer:pl.ver,createdAt:created,by:actorName()}:null;
 if(ko){S.keyOrders.unshift(ko);out.orders.push({type:'key',o:ko});}if(to){S.tokenOrders.unshift(to);out.orders.push({type:'token',o:to});}
 out.orders.forEach(x=>audit(draft?'order.draft':'order.place',x.o.no,{type:x.type,cc,qty:ord_qtyOf(x)}));
 if(!draft)out.invoices=ord_invoiceGroup(grp);return out;}
// issue invoice(s) for the orders of a group (drafts are re-priced from the current price list)
function ord_invoiceGroup(grp){const xs=ord_group(grp).filter(x=>!x.o.invoiceId&&x.o.status!=='cancelled');if(!xs.length)return[];const cc=xs[0].o.cc;const pl=priceList(cc);
 xs.forEach(x=>{x.o.priceVer=pl.ver;if(x.type==='key')x.o.unit=pl.key;else x.o.lines.forEach(l=>{l.unit=pl.tokens[l.plan][l.term];});x.o.status='awaiting_payment';});
 const ko=xs.find(x=>x.type==='key'),to=xs.find(x=>x.type==='token');const mode=xs[0].o.mode||'combined';
 const kl=ko?[{type:'key',qty:ko.o.qty,unit:ko.o.unit}]:[];const tl=to?to.o.lines.map(l=>({type:'token',plan:l.plan,term:l.term,qty:l.qty,unit:l.unit})):[];
 const groups=mode==='separate'&&ko&&to?[['keys',kl,[ko]],['tokens',tl,[to]]]:[[ko&&to?'combined':ko?'keys':'tokens',kl.concat(tl),[ko,to].filter(Boolean)]];
 return groups.map(([kind,lines,ords])=>{const inv=mkInvoice({cc,kind,lines,orderIds:ords.map(x=>x.o.id)});ords.forEach(x=>{x.o.invoiceId=inv.id;});return inv;});}

/* ---------- new order form ---------- */
function ord_draft(){const ccs=orgCountries();
 if(!S.ui.ord_draft)S.ui.ord_draft={cc:ccs[0],keys:String(ord_hasKeyOrder()?Math.max(500,orgMin().next):orgMin().first),tk:{},mode:'combined'};
 if(!ccs.includes(S.ui.ord_draft.cc))S.ui.ord_draft.cc=ccs[0];return S.ui.ord_draft;}
function ord_calc(d){const pl=priceList(d.cc);const lines=[];const keys=ord_qty(d.keys);
 if(keys>0)lines.push({type:'key',qty:keys,unit:pl.key,amount:r2(keys*pl.key)});
 ord_tokPlans().forEach(p=>TERMS.forEach(tm=>{const q=ord_qty(d.tk[pkgKey(p,tm)]);if(q>0){const u=pl.tokens[p][tm];lines.push({type:'token',plan:p,term:tm,qty:q,unit:u,amount:r2(q*u)});}}));
 const v=invVat();const net=r2(lines.reduce((a,l)=>a+l.amount,0));const vat=r2(net*v.rate);return{lines,keys:keys>0?keys:0,net,vat,total:r2(net+vat),v,pl};}
function ord_readForm(f){const d=ord_draft();const el=n=>f.elements[n];if(el('ord_keys'))d.keys=el('ord_keys').value;
 PLANS.forEach(p=>TERMS.forEach(tm=>{const k=pkgKey(p,tm);const e=el('ord_t_'+k);if(e)d.tk[k]=e.value;}));return d;}
function ord_keyHint(d){const q=ord_qty(d.keys);const min=ord_minKeys();
 if(isNaN(q))return{err:t('ord.f.errInt')};if(q>0&&q<min)return{err:t('ord.f.keys.errMin',{n:fmtNum(min)})};
 return{hint:t(ord_hasKeyOrder()?'ord.f.keys.minNext':'ord.f.keys.minFirst',{n:fmtNum(min)})};}
function ord_sumBody(d){const c=ord_calc(d);
 if(!c.lines.length)return `<p class="muted small">${t('ord.sum.empty')}</p>`;
 const hasK=c.lines.some(l=>l.type==='key'),hasT=c.lines.some(l=>l.type==='token');const n=(d.mode==='separate'&&hasK&&hasT)?2:1;
 const row=(a,b,cls)=>`<div class="ord_sr ${cls||''}"><span>${a}</span><span class="num">${b}</span></div>`;
 return `<div class="col g8">${c.lines.map(l=>`<div class="ord_sr"><span class="grow"><span class="ord_sl">${l.type==='key'?t('ord.keysT'):t('ord.tokT')+' '+esc(pkgLabel(l.plan,l.term))}</span><span class="xs faint num">${fmtNum(l.qty)} × ${money(l.unit,'USD')}</span></span><span class="num">${money(l.amount,'USD')}</span></div>`).join('')}</div>
 <hr class="sep" style="margin:14px 0">
 <div class="col g4">${row(t('ord.sum.subtotal'),money(c.net,'USD'),'muted')}${row(c.v.rate?t('ord.sum.vat5'):t('ord.sum.vat0'),money(c.vat,'USD'),'muted')}<div class="xs faint">${c.v.rate?t('ord.sum.vat5d'):t('ord.sum.vat0d')}</div></div>
 <div class="ord_tot"><span>${t('ord.sum.total')}</span><span class="num">${money(c.total,'USD')}</span></div>
 <div class="ord_inv1 small">${icon('file','sm')}<span>${t(n===2?'ord.sum.inv2':'ord.sum.inv1')} · ${esc(otaVal('OTA_NAME')||'OTA')}</span></div>`;}
function ord_refresh(f){const d=ord_draft();const b=$('#ord_sumbody');if(b)b.innerHTML=ord_sumBody(d);
 const h=$('#ord_keys-h');const sh=ord_keyHint(d);if(h){h.className=sh.err?'err':'hint';h.textContent=sh.err||sh.hint;}
 const si=$('#ord_keys');if(si){if(sh.err)si.setAttribute('aria-invalid','true');else si.removeAttribute('aria-invalid');}
 const q=ord_qty(d.keys);$$('.ord_chip').forEach(c=>c.setAttribute('aria-pressed',String(+c.dataset.arg===q)));
 PLANS.forEach(p=>TERMS.forEach(tm=>{const k=pkgKey(p,tm);const row=$('#ord_row_'+k);if(row)row.classList.toggle('on',ord_qty(d.tk[k])>0);}));
 const e=$('#ord_err');if(e&&ord_calc(d).lines.length)e.innerHTML='';}
document.addEventListener('input',e=>{const f=e.target.closest&&e.target.closest('form[data-form="ord_submit"]');if(!f)return;
 if(e.target.getAttribute('aria-invalid')&&e.target.id!=='ord_keys'){e.target.removeAttribute('aria-invalid');const h=f.querySelector('#'+CSS.escape(e.target.id)+'-h');if(h&&h.className==='err'){h.className='hint';h.textContent='';}}
 ord_readForm(f);ord_refresh(f);});

/* ---------- nav ---------- */
nav({key:'orders',label:()=>t('ord.nav.orders'),icon:'cart',href:'#orders',order:20,section:ord_sec,count:()=>S.keyOrders.concat(S.tokenOrders).filter(o=>o.status==='awaiting_payment'||o.status==='draft').length||null});
nav({key:'invoices',label:()=>t('ord.nav.invoices'),icon:'file',href:'#invoices',order:21,section:ord_sec,count:()=>S.invoices.filter(i=>i.status==='open').length||null});
nav({key:'shipments',label:()=>t('ord.nav.ship'),icon:'truck',href:'#shipments',order:22,section:ord_sec,count:()=>(S.shipments||[]).filter(h=>h.status!=='received').length||null});

/* ---------- route: orders ---------- */
function ord_summary(x){if(x.type==='key')return `<span class="num">${ord_keysN(x.o.qty)}</span>`;
 const tot=ord_qtyOf(x);const labels=x.o.lines.slice(0,2).map(l=>pkgLabel(l.plan,l.term)).join(', ')+(x.o.lines.length>2?' +'+(x.o.lines.length-2):'');
 return `<div class="col"><span class="num">${ord_toksN(tot)}</span><span class="xs faint" style="white-space:nowrap">${esc(labels)}</span></div>`;}
function ord_typeBadge(type){return type==='key'?ui.badge(icon('key','sm')+t('ord.type.key'),'accent'):ui.badge(icon('layers','sm')+t('ord.type.token'),'info');}
route('orders',{nav:'orders',render(){
 const newBtn=ui.btn(t('ord.new'),{kind:'primary',icon:'plus',href:'#order-new'});
 const all=ord_allOrders().sort((a,b)=>b.o.createdAt.localeCompare(a.o.createdAt)||b.o.no.localeCompare(a.o.no));
 if(!all.length)return ui.page({title:t('ord.title'),sub:t('ord.sub'),actions:newBtn,body:ui.card({body:ui.empty('cart',t('ord.empty.t'),t('ord.empty.p'),newBtn)})});
 const open=S.invoices.filter(i=>i.status==='open');const toPay=open.reduce((a,i)=>a+i.total,0);
 const ks=keyStats();let tk=0;PLANS.forEach(p=>TERMS.forEach(tm=>{tk+=tokensAvail(pkgKey(p,tm));}));
 const transit=(S.shipments||[]).filter(h=>h.status!=='received').reduce((a,h)=>a+h.qty,0);
 const kpis=`<div class="grid4" style="margin-bottom:16px">${ui.kpi(t('ord.kpi.topay'),money(toPay,'USD'),t('ord.kpi.topay.s',{n:open.length}),{href:'#invoices'})}${ui.kpi(t('ord.kpi.keys'),fmtNum(ks.avail),t('ord.kpi.keys.s',{n:fmtNum(ks.used)}),{href:'#codes'})}${ui.kpi(t('ord.kpi.toks'),fmtNum(tk),t('ord.kpi.toks.s'),{href:'#codes'})}${ui.kpi(t('ord.kpi.transit'),fmtNum(transit),t('ord.kpi.transit.s'),{href:'#shipments'})}</div>`;
 const rows=all.map(x=>{const inv=x.o.invoiceId&&invById(x.o.invoiceId);return{href:link('order',x.o.id),cells:[`<b class="mono ord_nw">${esc(x.o.no)}</b><br><span class="xs muted ord_nw">${t('ord.type.'+x.type)}</span>`,`<span style="white-space:nowrap">${fmtDate(x.o.createdAt)}</span>`,esc(ctyName(x.o.cc)),ord_summary(x),`<span class="num ord_nw">${money(ord_amountOf(x),'USD')}</span>`,inv?`<a class="mono ord_nw small" href="${link('invoice',inv.id)}">${esc(inv.number)}</a>`:'<span class="faint">—</span>',ord_stBadge(x.o)]};});
 const cols=[{label:t('ord.col.number')},{label:t('ord.col.date')},{label:t('ord.col.cc')},{label:t('ord.col.qty')},{label:t('ord.col.amount'),cls:'r'},{label:t('ord.col.invoice')},{label:t('ord.col.status')}];
 return ui.page({title:t('ord.title'),sub:t('ord.sub'),actions:newBtn,body:kpis+ui.note('info',t('ord.howItWorks'))+`<div style="height:16px"></div>`+ui.card({pad:false,body:ui.table(cols,rows)})});}});

/* ---------- route: new order ---------- */
route('order-new',{nav:'orders',render(){
 if(!S.org)return '';const d=ord_draft();const ccs=orgCountries();const pl=priceList(d.cc);
 if(!pl)return ui.page({title:t('ord.new'),crumbs:[[t('ord.title'),'#orders'],[t('ord.new')]],body:ui.card({body:ui.empty('price',t('ord.noPl.t'),t('ord.noPl.p'),ui.btn(t('ord.toPrices'),{href:'#prices'}))})});
 const block=orderBlock(d.cc);const sh=ord_keyHint(d);const q=ord_qty(d.keys);const num=n=>`<span class="ord_n" aria-hidden="true">${n}</span>`;
 const ccCard=ccs.length>1?ui.card({title:num(1)+t('ord.f.cc.h'),body:`<p class="muted small" style="margin-bottom:12px">${t('ord.f.cc.d')}</p>${ui.seg('ord_ccseg',ccs.map(c=>[c,esc(ctyName(c))]),d.cc,'ord_cc')}`}):'';
 const base=ccs.length>1?1:0;
 const chips=[1000,3000,5000,10000].map(v=>`<button type="button" class="ord_chip" data-act="ord_keysQ" data-arg="${v}" aria-pressed="${v===q}">${fmtNum(v)}</button>`).join('')+`<button type="button" class="ord_chip" data-act="ord_keysQ" data-arg="0" aria-pressed="${q===0}">${t('ord.f.keys.none')}</button>`;
 const keyCard=ui.card({title:num(base+1)+t('ord.f.keys.h'),body:`<p class="muted small" style="margin-bottom:14px">${t('ord.f.keys.d')}</p>
  <div class="field"><label for="ord_keys">${t('ord.f.keys.qty')}</label>
  <div class="row wrap g8"><input class="inp ord_qtybig num" id="ord_keys" name="ord_keys" inputmode="numeric" autocomplete="off" value="${esc(d.keys)}" ${sh.err?'aria-invalid="true"':''} aria-describedby="ord_keys-h ord_keys-u"><div class="row wrap g8" role="group" aria-label="${esc(t('ord.f.keys.qty'))}">${chips}</div></div>
  <span class="small muted" id="ord_keys-u">${t('ord.f.keys.unit',{p:`<b class="num">${money(pl.key,'USD')}</b>`,c:esc(ctyName(d.cc))})}</span>
  <span class="${sh.err?'err':'hint'}" id="ord_keys-h">${sh.err||sh.hint}</span></div><p class="xs faint" style="margin-top:8px">${t('ord.f.keys.sim')}</p>`});
 const models=allModels().filter(x=>x.model.planStatus==='approved');
 const grp=p=>{const ms=models.filter(x=>x.model.plan===p).map(x=>x.model.name);
  return `<div class="ord_grp"><div class="ord_grph"><b>${PLAN_NAME[p]}</b><span class="xs faint">${esc(t('ord.f.tok.models',{m:ms.slice(0,3).join(', ')+(ms.length>3?' +'+(ms.length-3):'')}))}</span></div>
  ${TERMS.map(tm=>{const k=pkgKey(p,tm);const v=d.tk[k]||'';const av=tokensAvail(k);
   return `<div class="ord_crrow ${ord_qty(v)>0?'on':''}" id="ord_row_${k}"><label for="ord_t_${k}" class="grow"><span class="ord_crt">${termLabel(tm)}${TERM_DISC[tm]?` <span class="badge xs">−${pct(TERM_DISC[tm])}</span>`:''}</span><span class="xs faint">${t('ord.f.tok.unit',{p:money(pl.tokens[p][tm],'USD')})}${av>0?' · '+t('ord.f.tok.avail',{n:fmtNum(av)}):''}</span></label><input class="inp num ord_crq" id="ord_t_${k}" name="ord_t_${k}" inputmode="numeric" autocomplete="off" placeholder="0" value="${esc(v)}" aria-label="${esc(t('ord.tokT')+' '+pkgLabel(p,tm))}"></div>`;}).join('')}</div>`;};
 const tp=ord_tokPlans();
 const tokCard=ui.card({title:num(base+2)+t('ord.f.tok.h')+` <span class="faint small" style="font-weight:500">· ${t('c.optional')}</span>`,body:tp.length?`<p class="muted small" style="margin-bottom:14px">${t('ord.f.tok.d')}</p><div class="${tp.length>1?'grid2':''}" style="align-items:start">${tp.map(grp).join('')}</div>`:ui.note('warn',`${t('ord.f.tok.locked')} <a href="#catalog">${t('ord.f.tok.toCatalog')} →</a>`)});
 const calc=ord_calc(d);const hasK=calc.lines.some(l=>l.type==='key'),hasT=calc.lines.some(l=>l.type==='token');
 const rc=(v,ti,de)=>`<button type="button" class="rc" role="radio" aria-checked="${d.mode===v}" data-act="ord_mode" data-arg="${v}"><b>${ti}</b><span class="small muted">${de}</span></button>`;
 const modeCard=ui.card({title:num(base+3)+t('ord.f.mode.h'),body:`<div class="radio-cards" role="radiogroup" aria-label="${esc(t('ord.f.mode.h'))}">${rc('combined',t('ord.f.mode.combined'),t('ord.f.mode.combined.d'))}${rc('separate',t('ord.f.mode.separate'),t('ord.f.mode.separate.d'))}</div>${calc.lines.length&&!(hasK&&hasT)?`<p class="xs faint" style="margin-top:10px">${t('ord.f.mode.single')}</p>`:''}`});
 const entCard=`<div class="ord_ent">${icon('shield','sm')}<div class="small"><b>${t('ord.f.from',{e:esc(otaVal('OTA_NAME')||'OTA')})}</b><div class="faint xs">${t('ord.f.fromD',{trn:esc(otaVal('OTA_TRN')||'—')})}</div></div></div>`;
 const allowed=can('p.orders');
 const side=`<aside class="ord_side"><section class="card"><div class="hd"><h2>${t('ord.sum.h')}</h2>${ui.badge('USD','accent')}</div><div class="bd"><div id="ord_sumbody">${ord_sumBody(d)}</div>
  <div id="ord_err" role="alert"></div>${block?`<div style="margin-top:12px">${ui.note('bad',esc(block))}</div>`:''}${allowed?'':`<div style="margin-top:12px">${ord_noPerm('p.orders')}</div>`}
  <div class="col g8" style="margin-top:16px">${ui.btn(t('ord.sum.submit'),{kind:'primary',size:'lg',block:true,type:'submit',disabled:!!block||!allowed})}${ui.btn(t('ord.sum.draft'),{block:true,act:'ord_saveDraft',disabled:!allowed})}</div>
  <p class="xs faint" style="margin-top:10px;text-align:center">${t('ord.sum.terms')}</p></div></section>${entCard}</aside>`;
 return ui.page({title:t('ord.new'),sub:t('ord.new.sub'),crumbs:[[t('ord.title'),'#orders'],[t('ord.new')]],
  body:`<form data-form="ord_submit" novalidate class="ord_layout"><div class="stack ord_mainc">${ccCard}${keyCard}${tokCard}${modeCard}</div>${side}</form>`});}});
function ord_validate(f,d){clearErrs(f);const errBox=$('#ord_err');if(errBox)errBox.innerHTML='';let bad=null;const err=(n,m)=>{setErr(f,n,m);if(!bad)bad=n;};
 const sh=ord_keyHint(d);if(sh.err)err('ord_keys',sh.err);
 PLANS.forEach(p=>TERMS.forEach(tm=>{const k=pkgKey(p,tm);if(isNaN(ord_qty(d.tk[k])))err('ord_t_'+k,t('ord.f.errInt'));}));
 const calc=ord_calc(d);
 if(!bad&&!calc.lines.length){if(errBox)errBox.innerHTML=`<div style="margin-top:12px">${ui.note('warn',t('ord.f.err.empty'))}</div>`;const si=$('#ord_keys');if(si)si.focus();return null;}
 if(bad){if(errBox)errBox.innerHTML=`<div style="margin-top:12px">${ui.note('bad',t('ord.f.err.fix'))}</div>`;const el=f.querySelector('[name="'+bad+'"]');if(el)el.focus();return null;}
 const toks=[];ord_tokPlans().forEach(p=>TERMS.forEach(tm=>{const q=ord_qty(d.tk[pkgKey(p,tm)]);if(q>0)toks.push([p,tm,q]);}));return{keys:calc.keys,toks,calc};}
FORM.ord_submit=f=>{if(!can('p.orders')){toast(t('c.noPerm',{r:roleName(actor().role)}),'bad');return;}const d=ord_readForm(f);if(orderBlock(d.cc))return;const v=ord_validate(f,d);if(!v)return;
 const r=ord_place(d.cc,v.keys,v.toks,d.mode,false);S.ui.ord_draft=null;
 const msg=t(r.invoices.length>1?'ord.placed2':'ord.placed',{n:r.orders.map(x=>x.o.no).join(' + '),i:r.invoices.map(i=>i.number).join(', ')});log(msg);toast(msg);go('invoice',r.invoices[0].id);};
Object.assign(ACT,{
 ord_keysQ(v){const f=$('form[data-form="ord_submit"]');if(f)ord_readForm(f);ord_draft().keys=String(v);rerender();},
 ord_cc(v){const f=$('form[data-form="ord_submit"]');if(f)ord_readForm(f);ord_draft().cc=v;rerender();},
 ord_mode(v){const f=$('form[data-form="ord_submit"]');if(f)ord_readForm(f);ord_draft().mode=v==='separate'?'separate':'combined';rerender();},
 ord_saveDraft(){const f=$('form[data-form="ord_submit"]');if(!f||!can('p.orders'))return;const d=ord_readForm(f);const v=ord_validate(f,d);if(!v)return;
  const r=ord_place(d.cc,v.keys,v.toks,d.mode,true);S.ui.ord_draft=null;const msg=t('ord.drafted',{n:r.orders.map(x=>x.o.no).join(' + ')});log(msg);toast(msg);go('order',r.orders[0].o.id);},
});

/* ---------- route: order detail ---------- */
function ord_notFound(title){return ui.page({title,crumbs:[[t('ord.title'),'#orders']],body:ui.card({body:ui.empty('search',title,t('ord.notfound.p'),ui.btn(t('ord.title'),{href:'#orders'}))})});}
route('order',{nav:'orders',render(id){const x=ord_find(id);if(!x)return ord_notFound(t('ord.notfound'));const o=x.o;
 const inv=o.invoiceId&&invById(o.invoiceId);const sib=ord_group(o.group).filter(y=>y.o.id!==o.id);
 const lines=x.type==='key'?[{type:'key',qty:o.qty,unit:o.unit,cc:o.cc}]:o.lines.map(l=>({type:'token',plan:l.plan,term:l.term,qty:l.qty,unit:l.unit}));
 const itemsCard=ui.card({title:t('ord.d.items'),pad:false,body:ui.table([{label:t('ord.doc.desc')},{label:t('ord.doc.qty'),cls:'r'},{label:t('ord.doc.unit'),cls:'r'},{label:t('ord.doc.amount'),cls:'r'}],
  lines.map(l=>({cells:[esc(lineDesc(l)),`<span class="num">${fmtNum(l.qty)}</span>`,`<span class="num ord_nw">${money(l.unit,'USD')}</span>`,`<span class="num ord_nw">${money(r2(l.qty*l.unit),'USD')}</span>`]}))),
  foot:`<span class="grow muted small">${t('ord.d.net',{v:o.priceVer||'—',c:esc(ctyName(o.cc))})}</span><b class="num">${t('c.total')}: ${money(ord_amountOf(x),'USD')}</b>`});
 const steps=[['draft',o.status==='draft'],['awaiting_payment',o.status==='awaiting_payment'],['paid',o.status==='paid']];
 const ci=o.status==='cancelled'?-1:['draft','awaiting_payment','paid'].indexOf(o.status);
 const tl=o.status==='cancelled'?ui.note('bad',t('ord.d.cancelled',{d:fmtDate(o.cancelledAt||o.createdAt)})+(inv&&inv.cnId?' · '+`<a href="${link('cnote',inv.cnId)}">${esc((S.creditNotes.find(c=>c.id===inv.cnId)||{}).number||'')}</a>`:'')):
  `<div class="timeline">${steps.map(([st],i)=>{const done=i<ci||(i===ci&&st==='paid');const cur=i===ci&&!done;
   const desc=st==='draft'?(i<ci?t('ord.tl.draft.done'):t('ord.tl.draft.d')):st==='awaiting_payment'?(inv?t('ord.tl.inv',{n:`<a href="${link('invoice',inv.id)}" class="mono">${esc(inv.number)}</a>`}):t('ord.tl.awaiting.d')):(done?t(x.type==='key'?'ord.tl.paid.keys':'ord.tl.paid.toks'):t('ord.tl.paid.d'));
   return `<div class="tl ${done?'done':cur?'cur':''}"><span class="dot">${done?icon('check','sm'):cur?'<span class="ord_pulse"></span>':''}</span><div class="grow ord_tlb"><b class="${!done&&!cur?'muted':''}">${t('ord.tl.'+st)}</b><div class="small ${!done&&!cur?'faint':'muted'}">${desc}</div></div></div>`;}).join('')}</div>`;
 const tlCard=ui.card({title:t('ord.d.track'),body:tl});
 const invCard=ui.card({title:t('ord.d.invoice'),pad:false,body:inv?`<div class="ord_list"><a class="ord_li" href="${link('invoice',inv.id)}"><span class="grow col"><b class="mono">${esc(inv.number)}</b><span class="xs faint">${t('ord.kind.'+inv.kind)}</span></span><span class="col" style="align-items:flex-end;gap:4px"><span class="num">${money(inv.total,'USD')}</span>${ord_invBadge(inv)}</span></a></div>`:`<p class="muted small cx_pad" style="padding:14px 18px">${t('ord.d.noInv')}</p>`});
 const sibCard=sib.length?ui.card({title:t('ord.d.sibling'),pad:false,body:`<div class="ord_list">${sib.map(y=>`<a class="ord_li" href="${link('order',y.o.id)}"><span class="grow col"><b class="mono">${esc(y.o.no)}</b><span class="xs faint">${t('ord.type.'+y.type)}</span></span>${ord_stBadge(y.o)}</a>`).join('')}</div>`}):'';
 const allowed=can('p.orders');let actions='';
 if(o.status==='draft')actions=ui.btn(t('ord.del.draft'),{kind:'ghost',icon:'trash',act:'ord_delDraft',arg:o.id,disabled:!allowed})+ui.btn(t('ord.d.issue'),{kind:'primary',icon:'file',act:'ord_issue',arg:o.group,disabled:!allowed||!!orderBlock(o.cc)});
 else if(o.status==='awaiting_payment'&&inv)actions=ui.btn(t('ord.cancel'),{kind:'ghost',icon:'x',act:'ord_cancel',arg:o.id,disabled:!allowed})+ui.btn(t('ord.d.pay'),{kind:'primary',icon:'card',href:link('invoice',inv.id)});
 const sub=`${t('ord.d.placed',{d:fmtDate(o.createdAt)})} · ${esc(ctyName(o.cc))} · <span class="num">${money(ord_amountOf(x),'USD')}</span>`;
 return ui.page({title:`<span class="row wrap g12"><span>${esc(o.no)}</span>${ord_typeBadge(x.type)}${ord_stBadge(o)}</span>`,sub,crumbs:[[t('ord.title'),'#orders'],[o.no]],actions,
  body:`<div class="ord_detail"><div class="stack">${o.status==='draft'&&orderBlock(o.cc)?ui.note('bad',esc(orderBlock(o.cc))):''}${tlCard}${itemsCard}</div><div class="stack">${invCard}${sibCard}</div></div>`});}});
Object.assign(ACT,{
 ord_issue(g){if(!can('p.orders'))return;const xs=ord_group(g);if(!xs.length||orderBlock(xs[0].o.cc))return;const invs=ord_invoiceGroup(g);if(!invs.length)return;
  xs.forEach(x=>audit('order.place',x.o.no,{type:x.type,from:'draft'}));const msg=t('ord.issued',{i:invs.map(i=>i.number).join(', ')});log(msg);toast(msg);go('invoice',invs[0].id);},
 ord_delDraft(id){const x=ord_find(id);if(!x||x.o.status!=='draft')return;modal(t('ord.del.draftT',{n:esc(x.o.no)}),`<p>${t('ord.del.draftP')}</p>`,ui.btn(t('c.cancel'),{act:'ovclose'})+ui.btn(t('ord.del.draft'),{kind:'danger',icon:'trash',act:'ord_delDraftDo',arg:id}));},
 ord_delDraftDo(id){const x=ord_find(id);if(!x||x.o.status!=='draft')return;if(x.type==='key')S.keyOrders=S.keyOrders.filter(o=>o.id!==id);else S.tokenOrders=S.tokenOrders.filter(o=>o.id!==id);
  audit('order.draft.delete',x.o.no,{});const msg=t('ord.del.draftDone',{n:x.o.no});log(msg);closeOverlay();toast(msg);go('orders');},
 ord_cancel(id){const x=ord_find(id);if(!x)return;const inv=invById(x.o.invoiceId);if(!inv||inv.status!=='open')return;const also=S.keyOrders.concat(S.tokenOrders).filter(o=>inv.orderIds.includes(o.id)&&o.id!==id);
  modal(t('ord.cancelT',{n:esc(x.o.no)}),`<p>${t('ord.cancelP',{i:'<b class="mono">'+esc(inv.number)+'</b>',cn:'<span class="mono">'+esc(docNo('CN',{peek:true}))+'</span>'})}</p>${also.length?ui.note('warn',t('ord.cancelAlso',{n:also.map(o=>esc(o.no)).join(', ')})):''}`,ui.btn(t('c.cancel'),{act:'ovclose'})+ui.btn(t('ord.cancel'),{kind:'danger',act:'ord_cancelDo',arg:inv.id}));},
 ord_cancelDo(invId){const inv=invById(invId);const cn=creditNote(inv,t('ord.cnReason.partner'));if(!cn)return;const msg=t('ord.cn.done',{i:inv.number,c:cn.number});log(msg);closeOverlay();toast(msg);rerender();},
});

/* ---------- route: invoices + credit notes ---------- */
route('invoices',{nav:'invoices',render(){
 const f=S.ui.ord_invF||'all';const all=S.invoices.slice().sort((a,b)=>b.createdAt.localeCompare(a.createdAt)||b.number.localeCompare(a.number));
 const list=all.filter(i=>f==='all'||(f==='paid'?i.status==='paid':f==='cancelled'?i.status==='cancelled':i.status==='open'));
 const per=50;const pages=Math.max(1,Math.ceil(list.length/per));const pg=clamp(S.ui.ord_invP||1,1,pages);
 const cols=[{label:t('ord.col.number')},{label:t('ord.col.date')},{label:t('ord.col.kind')},{label:t('ord.col.cc')},{label:t('ord.col.amount'),cls:'r'},{label:t('ord.col.due')},{label:t('ord.col.status')}];
 const rows=list.slice((pg-1)*per,pg*per).map(i=>({href:link('invoice',i.id),cells:[`<b class="mono ord_nw">${esc(i.number)}</b>`,`<span class="ord_nw">${fmtDate(i.createdAt)}</span>`,`<span class="ord_nw">${t('ord.kind.'+i.kind)}</span>`,esc(ctyName(i.cc)),`<span class="num ord_nw">${money(i.total,'USD')}</span>`,`<span class="ord_nw ${invStatus(i)==='overdue'?'':'muted'}">${i.status==='open'?fmtDate(i.dueAt):'—'}</span>`,ord_invBadge(i)+(i.reported&&i.status==='open'?' '+ui.badge(icon('clock','sm'),'info'):'')]}));
 const n=k=>all.filter(i=>k==='open'?i.status==='open':i.status===k).length;
 const tb=`<div class="toolbar">${ui.seg('ord_invf',[['all',t('c.all')+` <span class="faint">${all.length}</span>`],['open',t('ord.inv.f.open')+` <span class="faint">${n('open')}</span>`],['paid',t('ord.inv.f.paid')+` <span class="faint">${n('paid')}</span>`],['cancelled',t('ord.inv.f.cancelled')+` <span class="faint">${n('cancelled')}</span>`]],f,'ord_invF')}</div>`;
 const cns=S.creditNotes||[];
 const cnCard=cns.length?ui.card({title:t('ord.cn.title'),pad:false,body:ui.table([{label:t('ord.col.number')},{label:t('ord.col.date')},{label:t('ord.cn.for')},{label:t('ord.col.amount'),cls:'r'},{label:t('ord.cn.reason')}],cns.map(c=>({href:link('cnote',c.id),cells:[`<b class="mono ord_nw">${esc(c.number)}</b>`,`<span class="ord_nw">${fmtDate(c.createdAt)}</span>`,`<span class="mono ord_nw">${esc(c.invoiceNo)}</span>`,`<span class="num ord_nw">−${money(c.total,'USD')}</span>`,`<span class="small muted">${esc(c.reason)}</span>`]})))}):'';
 const body=!all.length?ui.card({body:ui.empty('file',t('ord.inv.empty'),t('ord.inv.empty.p'),ui.btn(t('ord.new'),{kind:'primary',icon:'plus',href:'#order-new'}))}):
  `<div class="stack">${ui.card({pad:false,body:tb+ui.table(cols,rows,{empty:ui.empty('filter',t('ord.inv.emptyF'),'')})+(list.length>per?ui.pager(pg,list.length,per,'ord_invP'):'')})}${cnCard}</div>`;
 return ui.page({title:t('ord.inv.title'),sub:t('ord.inv.sub'),actions:ui.btn(t('ord.new'),{icon:'plus',href:'#order-new'}),body});}});
Object.assign(ACT,{ord_invF(v){S.ui.ord_invF=v;S.ui.ord_invP=1;rerender();},ord_invP(v){S.ui.ord_invP=+v;rerender();}});

/* ---------- route: invoice document ---------- */
function ord_purpose(i){return 'Invoice '+i.number+(i.buyer&&i.buyer.code?' · '+i.buyer.code:'');}
// bank details field by field, in the order a payer fills them in (N/A fields are skipped)
function ord_payFields(i){const e=i.seller||S.ota;const v=k=>{const x=e[k];return x&&String(x).trim()?String(x).trim():null;};
 return [['ord.pf.benef',v('OTA_BANK_BENEF')||v('OTA_NAME')],['ord.pf.benefAddr',v('OTA_ADDR_EN')],['ord.pf.account',v('OTA_BANK_ACCOUNT'),1],['ord.pf.iban',v('OTA_BANK_IBAN'),1],['ord.pf.bank',v('OTA_BANK_NAME')],['ord.pf.bankAddr',v('OTA_BANK_ADDR')],['ord.pf.swift',v('OTA_BANK_SWIFT'),1],
  ['ord.pf.inter',v('OTA_BANK_INTER')],['ord.pf.interSwift',v('OTA_BANK_INTER_SWIFT'),1],['ord.pf.amount',i.total.toFixed(2),1],['ord.pf.cur',v('OTA_BANK_CUR')||'USD',1],['ord.pf.details',ord_purpose(i)]].filter(x=>x[1]);}
function ord_payText(i){return ord_payFields(i).map(([k,v])=>t(k)+': '+v).join('\n');}
// native print buttons for the ops-docs print views (#opsdoc--TYPE--ID); data-ops-inj makes 75_opsdocs skip its own injection
function ord_printBtn(type,id,label){return `<a class="btn ghost" data-ops-print="${type}" data-ops-inj="1" href="${link('opsdoc',type,id)}">${icon('printer','sm')}<span>${esc(label)}</span></a>`;}
function ord_asBtn(role){const u=users().find(x=>x.role===role);return u?ui.btn(t('ord.switchTo',{r:roleName(role)}),{size:'sm',kind:'ghost',icon:'users',act:'ord_as',arg:u.id}):'';}
route('invoice',{nav:'invoices',render(id){const i=invById(id);if(!i)return ord_notFound(t('ord.notfound.inv'));
 const e=i.seller||S.ota;const st=invStatus(i);const L2=(S.org&&S.org.lang2)||'ru';const ev=k=>e[k]&&String(e[k]).trim()?String(e[k]).trim():null;
 const hasIssue=i.lines.some(l=>l.type!=='xchg');
 let banner;
 if(st==='paid')banner=ui.note('ok',`<b>${t('ord.doc.banner.paid',{d:fmtDate(i.paidAt)})}</b> ${t(i.kind==='exchange'?'ord.doc.xchgDone':'ord.doc.issuedNote')} <a href="#codes">${t('ord.doc.toCodes')} →</a>`,'check');
 else if(st==='cancelled'){const cn=(S.creditNotes||[]).find(c=>c.id===i.cnId);banner=ui.note('bad',`<b>${t('ord.doc.banner.cancelled',{d:fmtDate(i.cancelledAt||i.createdAt)})}</b>${cn?' '+t('ord.doc.byCn',{c:`<a class="mono" href="${link('cnote',cn.id)}">${esc(cn.number)}</a>`}):''}`);}
 else if(st==='overdue')banner=ui.note('bad',`<b>${t('ord.doc.banner.overdue',{d:fmtDate(i.dueAt)})}</b>`);
 else banner=ui.note('info',`<b>${t('ord.doc.banner.open',{d:fmtDate(i.dueAt)})}</b> ${t(i.kind==='exchange'?'ord.doc.banner.xchg':'ord.doc.banner.issue')}`,'clock');
 if(i.reported&&i.status==='open')banner+=`<div style="margin-top:8px">${ui.badge(icon('clock','sm')+t('ord.doc.reported'),'info')}</div>`;
 let admin='';
 if(S.admin){const parts=[];
  if(i.vatWarn)parts.push(`<div>${ui.badge(t('ord.doc.vatWarnB'),'bad')} ${t('ord.doc.vatWarn')}</div>`);
  if(i.status==='open')parts.push(`<span>${t('ord.doc.markPaidNote')}</span><span class="row wrap g8">${ui.btn(t('ord.doc.markPaid'),{kind:'primary',size:'sm',icon:'check',act:'ord_markPaid',arg:i.id,disabled:!can('ota.payments')})}${can('ota.payments')?'':ord_asBtn('ota_finance')}</span>`);
  if(i.status!=='cancelled'){const used=i.status==='paid'?invUsed(i):0;parts.push(`<span class="row wrap g8">${ui.btn(t('ord.doc.cn'),{size:'sm',kind:'ghost',icon:'x',act:'ord_cnAsk',arg:i.id,disabled:!can('ota.cn')||used>0})}${used>0?`<span class="xs faint">${t('ord.doc.cnUsed',{n:fmtNum(used)})}</span>`:''}</span>`);}
  if(parts.length)admin=ui.note('admin',`<div class="col g8"><b>${t('ord.adm.h')}</b>${parts.join('')}</div>`);}
 const actions=`<span class="row wrap g8 ord_noprint">${ord_printBtn('inv',i.id,t('ord.pr.inv'))}${i.status!=='cancelled'?ui.btn(t('ord.doc.copyAll'),{icon:'copy',act:'ord_copyPay',arg:i.id}):''}${i.status==='open'&&!i.reported?ui.btn(t('ord.doc.report'),{kind:'primary',icon:'check',act:'ord_report',arg:i.id}):''}</span>`;
 const party=(lbl,name,lines)=>`<div class="ord_party"><span class="ord_lbl">${lbl}</span><b>${esc(name)}</b>${lines.filter(Boolean).map(l=>`<span>${l}</span>`).join('')}</div>`;
 const b=i.buyer||{};const refs=[i.mpa?['ord.doc.mpa',i.mpa]:null,i.of?['ord.doc.of',i.of]:null].filter(Boolean);
 const doc=`<article class="card ord_doc" aria-label="${esc('Tax Invoice '+i.number)}">
  <header class="ord_dhd"><div class="col"><b class="ord_dbrand">${esc(ev('OTA_NAME')||'')}</b><span class="xs faint">${esc(ev('OTA_ADDR_EN')||'')}</span></div>
   <div class="ord_dtitle"><h2>Tax Invoice <span class="mono">${esc(i.number)}</span></h2><span class="xs faint">${t('ord.doc.titleL')}</span>${ord_invBadge(i)}</div></header>
  <div class="ord_meta"><div><span class="ord_lbl">${t('ord.doc.no')}</span><b class="mono" style="font-size:12.5px">${esc(i.number)}</b></div><div><span class="ord_lbl">${t('ord.doc.date')}</span><b>${fmtDate(i.createdAt)}</b></div><div><span class="ord_lbl">${t('ord.doc.due')}</span><b>${fmtDate(i.dueAt)}</b></div><div><span class="ord_lbl">${t('ord.doc.currency')}</span><b>USD</b></div></div>
  ${refs.length?`<div class="ord_meta">${refs.map(([k,v])=>`<div><span class="ord_lbl">${t(k)}</span><b class="mono" style="font-size:12.5px">${esc(v)}</b></div>`).join('')}</div>`:''}
  <div class="ord_parties">${party(t('ord.doc.seller'),ev('OTA_NAME')||'',[esc(ev('OTA_ADDR_EN')||''),[ev('OTA_REGNO')?'Registration no. '+esc(ev('OTA_REGNO')):'',ev('OTA_LICENCE')?'Licence no. '+esc(ev('OTA_LICENCE')):''].filter(Boolean).join(' · '),ev('OTA_TRN')?'TRN (VAT) '+esc(ev('OTA_TRN')):''])}
   ${party(t('ord.doc.buyer'),b.name||'—',[esc(b.address||''),b.regNo?'Company no. '+esc(b.regNo):'',b.taxId?'Tax / VAT no. '+esc(b.taxId):''])}</div>
  <div class="tblwrap"><table class="tbl ord_lines"><thead><tr><th scope="col">#</th><th scope="col">${t('ord.doc.desc')}</th><th scope="col" class="r">${t('ord.doc.qty')}</th><th scope="col" class="r">${t('ord.doc.unit')}</th><th scope="col" class="r">${t('ord.doc.amount')}</th></tr></thead>
   <tbody>${i.lines.map((l,n)=>`<tr><td class="faint">${n+1}</td><td><span>${esc(lineDescEn(l))}</span>${L2!=='en'?`<br><span class="xs faint">${esc(lineDescL2(l,L2))}</span>`:''}${l.type==='key'?`<br><span class="xs muted">Approved Country: ${esc(ctyNameEn(l.cc||i.cc))}</span>`:''}</td><td class="r num">${fmtNum(l.qty)}</td><td class="r num ord_nw">${money(l.unit,'USD')}</td><td class="r num ord_nw">${money(l.amount,'USD')}</td></tr>`).join('')}</tbody></table></div>
  <div class="ord_totals"><div><span>${t('ord.sum.subtotal')}</span><span class="num">${money(i.net,'USD')}</span></div><div><span>${esc(i.vatRate?'VAT 5%':'VAT 0%')}</span><span class="num">${money(i.vat,'USD')}</span></div>
   <div class="ord_novat">${esc(i.vatLabel)}${L2!=='en'?' / '+esc(ord_vatLine(i,L2)):''}</div>
   <div class="ord_grand"><span>${t('ord.doc.total')}</span><span class="num">${money(i.total,'USD')}</span></div></div>
  <p class="xs muted">${t('ord.doc.simNote')}</p><p class="xs muted">${t('ord.doc.terms')}</p>
  ${i.status!=='cancelled'?`<div class="ord_pay"><span class="ord_lbl">${t('ord.doc.bank')}</span><p class="xs faint" style="margin:2px 0 10px">${t('ord.pf.hint')}</p>
   <div class="ord_pf">${ord_payFields(i).map(([k,v,mono])=>`<div class="ord_pfr"><span class="ord_pfl">${t(k)}</span><span class="ord_pfv ${mono?'mono':''}">${esc(v)}</span>${ui.iconbtn('copy',t('ord.doc.copy')+': '+t(k),{act:'copy',arg:v})}</div>`).join('')}</div></div>`:''}
  <footer class="ord_dft xs faint"><span>© ${new Date(i.createdAt).getFullYear()} ${esc(ev('OTA_NAME')||'')}. All rights reserved · Confidential</span><b class="mono">${esc(i.number)}</b></footer></article>`;
 const ords=S.keyOrders.concat(S.tokenOrders).filter(o=>i.orderIds.includes(o.id));
 const sub=`${t('ord.kind.'+i.kind)} · ${esc(ctyName(i.cc))} · <span class="num">${money(i.total,'USD')}</span>${ords.length?' · '+ords.map(o=>`<a class="mono" href="${link('order',o.id)}">${esc(o.no)}</a>`).join(', '):''}`;
 return ui.page({title:esc(i.number),sub,crumbs:[[t('ord.inv.title'),'#invoices'],[i.number]],actions,
  body:`<div class="ord_docwrap"><div class="stack ord_noprint" style="margin-bottom:16px">${banner}${admin}</div>${doc}</div>`});}});
Object.assign(ACT,{
 ord_markPaid(id){const i=invById(id);if(!i||!can('ota.payments'))return;tick(5);if(!invoicePaid(i))return;
  const k=i.lines.filter(l=>l.type==='key').reduce((a,l)=>a+l.qty,0),tk=i.lines.filter(l=>l.type==='token').reduce((a,l)=>a+l.qty,0);
  const msg=t('ord.doc.paidToast',{n:i.number})+(k||tk?' · '+t('ord.doc.issuedToast',{k:fmtNum(k),t:fmtNum(tk)}):'');log(msg);toast(msg);rerender();},
 ord_report(id){const i=invById(id);if(!i)return;i.reported=true;i.reportedAt=iso(now());audit('invoice.reported_paid',i.number,{});log(i.number+': '+t('ord.doc.reported'));toast(t('ord.doc.reportedToast'));rerender();},
 ord_copyPay(id){const i=invById(id);if(i)copyText(ord_payText(i));},
 ord_print(){try{window.print();}catch(e){}},
 ord_as(id){ACT.setActor(id);},
 ord_cnAsk(id){const i=invById(id);if(!i||!can('ota.cn'))return;
  modal(t('ord.cn.askT',{n:esc(i.number)}),`<form id="ord_cnF" data-form="ord_cn" class="stack" novalidate><input type="hidden" name="id" value="${esc(id)}"><p>${t(i.status==='paid'?'ord.cn.askPaid':'ord.cn.askOpen',{cn:'<span class="mono">'+esc(docNo('CN',{peek:true}))+'</span>',a:money(i.total,'USD')})}</p>${ui.field({id:'ord_cnr',label:t('ord.cn.reason'),value:t('ord.cnReason.ota'),attrs:'maxlength="160"'})}</form>`,
   ui.btn(t('c.cancel'),{act:'ovclose'})+`<button class="btn danger" type="submit" form="ord_cnF"><span>${t('ord.doc.cn')}</span></button>`);},
});
FORM.ord_cn=f=>{const d=formData(f);const i=invById(d.id);if(!i||!can('ota.cn'))return;const r=String(d.ord_cnr||'').trim();if(!r){setErr(f,'ord_cnr',t('c.required'));return;}
 const cn=creditNote(i,r);if(!cn){toast(t('ord.cn.fail'),'bad');return;}const msg=t('ord.cn.done',{i:i.number,c:cn.number});log(msg);closeOverlay();toast(msg);rerender();};

/* ---------- route: credit note ---------- */
